def digest(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def command(args, timeout=20):
    value = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=timeout)
    if value.returncode:
        raise RuntimeError('Command failed: '+args[0]+' '+value.stdout.decode(errors='replace')[-500:])
    return value.stdout.decode(errors='replace')


def service(*args):return command(['systemctl']+list(args))


def get(port, route):
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open('http://127.0.0.1:%d%s'%(port,route),timeout=2) as response:return json.load(response)


def camera():
    value=get(8790,'/health')
    result={k:value.get(k) for k in ('pid','capture_frames','detected_frames','capture_hz',
        'detection_hz','observation_age_ms','camera_error','detector_error','dpu_schedule','pipeline_metrics')}
    identity=value.get('identity') or {}
    result.update(identity_backend=identity.get('backend'),face_targets=identity.get('face_targets'),
        shadow=(identity.get('feature_inference') or {}).get('shadow'))
    return result


def face_count():
    return get(8790,'/v1/ui/status').get('modules',{}).get('identity',{}).get('face_count',0)


def ui_idle():
    value=get(8783,'/api/state')
    assert value.get('phase')=='IDLE' and not value.get('playing') and not value.get('paused'), 'GUI is busy'
    assert value.get('local_recording',{}).get('state')!='RECORDING','Recording is active'
    assert not value.get('local_transcription',{}).get('service',{}).get('pending'),'Transcription is pending'
    return {k:value.get(k) for k in ('phase','playing','paused','audio_output_state')}


def runtime_for(pid):
    args=(Path('/proc')/str(pid)/'cmdline').read_bytes().split(b'\0')
    source=next(Path(x.decode()) for x in args if x.endswith(b'/board_camera_motion.py'))
    return source.parent.parent,Path(args[args.index(b'--config')+1].decode())


def single_owner(pid):
    owners=[]
    for proc in Path('/proc').glob('[0-9]*'):
        try:
            if any(x.endswith(b'/board_camera_motion.py') for x in (proc/'cmdline').read_bytes().split(b'\0')):
                owners.append(int(proc.name))
        except OSError:pass
    assert owners==[pid] or sorted(owners)==[pid], 'Unexpected camera processes: '+repr(owners)
    assert int(service('show','aura-camera-ui.service','-p','MainPID','--value').strip())==pid
    lock=Path('/run/aura-person-dpu.lock').stat()
    found=[]
    for line in Path('/proc/locks').read_text().splitlines():
        parts=line.split()
        if len(parts)<6 or parts[1]!='FLOCK' or parts[3]!='WRITE':continue
        dev=parts[5].split(':')
        if (len(dev)==3 and int(dev[0],16)==os.major(lock.st_dev)
                and int(dev[1],16)==os.minor(lock.st_dev) and int(dev[2])==lock.st_ino):found.append(int(parts[4]))
    assert found==[pid], 'DPU process owner lock mismatch: '+repr(found)


def cpu():
    values=list(map(int,Path('/proc/stat').read_text().splitlines()[0].split()[1:9]))
    return {'mono':time.monotonic(),'total':sum(values),'idle':values[3]+values[4]}


def cpu_delta(first,last):
    total=last['total']-first['total']
    return {'duration_s':last['mono']-first['mono'],
        'cpu_percent_of_board':100*(total-last['idle']+first['idle'])/total if total>0 else None}


def atomic(path,raw):
    path=Path(path);temp=path.with_name(path.name+'.owned-shadow-'+str(os.getpid()))
    with temp.open('xb') as out:out.write(raw);out.flush();os.fsync(out.fileno())
    os.replace(str(temp),str(path))


def write_report(root,report):atomic(root/'deployment-result.json',(json.dumps(report,indent=2)+'\n').encode())


def rollback_source(root):
    # An independent timer needs only these backed-up bytes and this script.
    return '''import fcntl,os,subprocess
from pathlib import Path
root=Path(ROOT_VALUE)
lock=(root/'rollback.lock').open('a+')
fcntl.flock(lock,fcntl.LOCK_EX)
unit=Path('/etc/systemd/system/aura-camera-ui.service')
old=(root/'camera.service.original').read_bytes();new=(root/'camera.service.candidate').read_bytes()
assert unit.read_bytes() in (old,new),'Unrelated later camera unit; refusing overwrite'
subprocess.run(['systemctl','stop','aura-camera-ui.service'],check=True,timeout=40)
assert unit.read_bytes() in (old,new),'Unit changed while stopping; refusing overwrite'
temp=unit.with_name(unit.name+'.shadow-rollback-'+str(os.getpid()))
temp.write_bytes(old);os.replace(str(temp),str(unit))
subprocess.run(['systemctl','daemon-reload'],check=True,timeout=15)
subprocess.run(['systemctl','start','--no-block','aura-camera-ui.service'],check=True,timeout=15)
'''.replace('ROOT_VALUE',repr(str(root)))


def kernel_cursor():
    raw=command(['journalctl','-k','-n','0','--show-cursor','--no-pager'],timeout=5)
    return next(x.split(': ',1)[1] for x in raw.splitlines() if x.startswith('-- cursor: '))


def audio_warnings(cursor):
    raw=command(['journalctl','-k','--after-cursor='+cursor,'-o','json','--no-pager','-n','5000'],timeout=10)
    count=0
    for line in raw.splitlines():
        try:message=json.loads(line).get('MESSAGE','')
        except ValueError:continue
        count+=int('WARN: HC couldn\'t access mem fast enough' in message)
    return count


def healthy(state,shadow=False):
    assert not state['camera_error'] and not state['detector_error'],'Camera/detector error'
    assert state['observation_age_ms'] is not None and state['observation_age_ms']<750,'Primary observation expired'
    assert state['identity_backend']=='WINDOWS_CPU_SFACE_ORT','Primary identity backend changed'
    face=state.get('face_targets') or {}
    assert face.get('backend')=='DPU_YUNET_INT8' and face.get('ready') and not face.get('error'),'YuNet baseline lost'
    jobs=(state.get('dpu_schedule') or {}).get('optional',{})
    for key in ('yunet','sface'):
        job=jobs.get(key,{})
        assert not job.get('disabled') and not job.get('overruns',0),'Optional task overrun: '+key
    if shadow:
        value=state.get('shadow') or {}
        assert value.get('ready') and not value.get('failures') and not value.get('last_error'),'Shadow unavailable'
        assert value.get('mode')=='SHADOW_ONLY_WINDOWS_IDENTITY' and value.get('templates_written')==0




def affinity_rows(folder,pid):
    path=folder/('affinity-'+str(pid)+'.jsonl')
    raw=path.read_bytes();assert len(raw)<=65536
    return [json.loads(line) for line in raw.splitlines() if line]

def proc_start(path):
    return int(Path(path).read_text().rsplit(')',1)[1].split()[19])

def affinity_snapshot(folder,pid):
    rows=affinity_rows(folder,pid)
    baseline=[r for r in rows if r['event']=='PROCESS_BASELINE'];assert len(baseline)==1
    assert baseline[0]['pid']==pid and baseline[0]['allowed_cpus']==[0,1,2,3]
    assert baseline[0]['gil_seconds']==.005
    assert baseline[0]['policy_sha256']==PAYLOAD_SHA['example_policy_kv260.json']
    assert baseline[0]['target_sha256']=='1e0e6f0b8881c2d4d4cf81a2527e79d063e673eeba1d069e33bdde2608303005'
    assert baseline[0]['role_source_sha256']==ROLE_PINS
    assert sum(r['event']=='ALL_ROLES_COMMITTED' for r in rows)==1
    applied=[r for r in rows if r['event']=='APPLIED'];assert len(applied)==4
    assert {r['role'] for r in applied}==set(AFFINITY_POLICY['roles'])
    assert not any(r['event'] in ('ABORT_OWNED_PROCESS','RESTORED','CLOSED') for r in rows)
    process_start=proc_start('/proc/'+str(pid)+'/stat');bindings=[]
    for row in applied:
        ident=row['identity'];tid=ident['tid'];task=Path('/proc')/str(pid)/'task'/str(tid)
        assert ident['pid']==pid and ident['process_starttime']==process_start
        assert proc_start(task/'stat')==ident['thread_starttime']
        status=(task/'status').read_text().splitlines()
        assert int(next(x.split()[1] for x in status if x.startswith('Tgid:')))==pid
        actual=sorted(os.sched_getaffinity(tid))
        assert proc_start(task/'stat')==ident['thread_starttime']
        assert proc_start('/proc/'+str(pid)+'/stat')==ident['process_starttime']
        assert row['old_cpus']==[0,1,2,3]
        assert actual==row['actual_cpus']==AFFINITY_POLICY['roles'][row['role']]
        bindings.append({'role':row['role'],'identity':ident,'actual_cpus':actual})
    # Observe remaining tasks without guessing their native/runtime roles.
    tasks=[]
    for task in sorted((Path('/proc')/str(pid)/'task').iterdir()):
        try:tasks.append({'tid':int(task.name),'comm':(task/'comm').read_text().strip(),
                          'cpus':sorted(os.sched_getaffinity(int(task.name)))})
        except (FileNotFoundError,ProcessLookupError):pass
    return {'pid':pid,'mono':time.monotonic(),'bindings':bindings,'tasks':tasks,
        'scope':'two bounded snapshots; unknown descendants may inherit creator mask; not exclusive CPUs'}

def affinity_shutdown(folder,pid):
    rows=affinity_rows(folder,pid)
    applied=[r for r in rows if r['event']=='APPLIED']
    restored=[r for r in rows if r['event']=='RESTORED']
    by_role={r['role']:r for r in restored}
    clean=(len(applied)==len(restored)==4 and len(by_role)==4
        and all(r['role'] in by_role and by_role[r['role']]['identity']==r['identity']
                and by_role[r['role']]['actual_cpus']==r['old_cpus'] for r in applied)
        and sum(r['event']=='CLOSED' for r in rows)==1
        and not any(r['event']=='ABORT_OWNED_PROCESS' for r in rows))
    return {'clean_selected_thread_restoration_and_close':clean,'events':rows,
        'scope':'SIGKILL or process exit may omit events; missing restoration is not reported as clean'}


def main():
    assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()=='215c4292-ce84-4828-9827-83c32ba66564'
    assert digest(UNIT)==UNIT_SHA
    before=camera();healthy(before);single_owner(before['pid']);idle=ui_idle()
    assert sorted(os.sched_getaffinity(before['pid']))==[0,1,2,3]
    assert before.get('shadow') is None
    original_config=BASE/'board_camera_ui.json';identity_path=BASE/'board_identity.json'
    assert runtime_for(before['pid'])==(BASE/'aura',original_config)
    for name,expected in BASELINE.items():assert digest(BASE/'aura'/name)==expected
    identity=json.loads(identity_path.read_text());assert identity['face_backend']['kind']=='dpu_yunet'
    assert identity['feature_backend']=={'kind':'windows_sface','host':'192.168.50.1','port':8792,'timeout_ms':650}
    for key in ('model','manifest'):assert digest(identity['face_backend'][key])==identity['face_backend'][key+'_sha256']
    for path in [identity['database']]+([identity['enrollment_photos']['directory']] if identity.get('enrollment_photos') else []):
        assert (BASE/'aura').resolve() not in Path(path).expanduser().resolve().parents
    usb=Path('/sys/bus/usb/devices/1-1.2')
    assert (usb/'idVendor').read_text().strip()=='17ef' and (usb/'idProduct').read_text().strip()=='a03b'
    assert (usb/'devnum').read_text().strip()=='4','Revalidate endpoint mapping before fixed-boot observation'
    original_unit=UNIT.read_bytes()
    protected={str(p):digest(p) for p in [original_config,identity_path,
        Path('/home/root/aura-speech-motion-20261021/de989bf024a9/startup/config.json'),
        Path('/home/root/.local/share/aura/handsfree_dialogue.json')]}
    unit_pids={name:service('show',name,'-p','MainPID','--value').strip()
        for name in ['aura-avatar-ui.service','xserver-nodm.service']}
    folder=Path('/home/root/aura-dpu-vision-20261021/affinity-live')/('cbee206f503bab01-'+str(os.getpid()))
    folder.mkdir(parents=True,exist_ok=False);candidate=folder/'aura'
    shutil.copytree(BASE/'aura',candidate,ignore=shutil.ignore_patterns('__pycache__','*.sqlite*','*.db'))

    patch=Path('/home/root/aura-dpu-vision-20261021/staging')/BUNDLE_SHA[:16]/'bundle.tar.gz'
    assert digest(patch)==BUNDLE_SHA
    with tarfile.open(patch,'r:gz') as archive:
        manifest=json.load(archive.extractfile('candidate-manifest.json'))
        assert set(archive.getnames())==set(SOURCE_HASHES)|{'candidate-manifest.json'}
        for name,sha in SOURCE_HASHES.items():
            item=archive.getmember(name);assert item.isfile() and item.size<=65536
            data=archive.extractfile(item).read();assert hashlib.sha256(data).hexdigest()==sha
            assert sha==manifest['files'][name]['sha256'];ast.parse(data.decode())
            target=candidate/name;target.parent.mkdir(parents=True,exist_ok=True)
            assert not target.is_symlink();target.write_bytes(data)
    path=candidate/'board/vision/ui_camera_service.py'
    updated=original_unit.decode().replace(str(BASE/'aura'),str(candidate))
    assert updated.count('[Service]\n')==1
    updated=updated.replace('[Service]\n','[Service]\nEnvironment="AURA_PIPELINE_METRICS=1"\nEnvironment="AURA_DPU_DIAGNOSTICS=1"\nEnvironment="AURA_THREAD_SCHED_DIAGNOSTICS=switches"\n').encode()

    import base64
    for name,encoded in PAYLOAD_B64.items():
        item=folder/name;item.write_bytes(base64.b64decode(encoded))
        assert digest(item)==PAYLOAD_SHA[name]
    for role,(relative,qualname,expected) in ROLE_SOURCES.items():
        assert digest(candidate/relative)==expected,role
    target=str(candidate/'tools/board_camera_motion.py')
    assert digest(target)=='1e0e6f0b8881c2d4d4cf81a2527e79d063e673eeba1d069e33bdde2608303005'
    text=updated.decode();assert text.count(target)==1
    text=text.replace(target,str(folder/'affinity_camera_launcher.py')+' '+target)
    assert text.count('[Service]\n')==1
    text=text.replace('[Service]\n','[Service]\nEnvironment="AURA_EXPERIMENT_AFFINITY=1"\n'
        +'Environment="AURA_EXPERIMENT_AFFINITY_POLICY='+str(folder/'example_policy_kv260.json')+'"\n')
    updated=text.encode()
    assert updated!=original_unit

    (folder/'camera.service.original').write_bytes(original_unit)
    (folder/'camera.service.candidate').write_bytes(updated)
    (folder/'rollback.py').write_text(rollback_source(folder))
    report={'scope':'CPU_AFFINITY_DUAL_MODEL_120S_ALWAYS_RESTORED',
        'passed':False,'complete':False,'phase':'BASELINE','root':str(folder),
        'camera_before':before,'ui_before':idle,'original_unit_sha256':UNIT_SHA,
        'candidate_ui_sha256':SOURCE_HASHES['board/vision/ui_camera_service.py'],'source_hashes':SOURCE_HASHES,
        'original_runtime':str(BASE/'aura'),'candidate_runtime':str(candidate),
        'candidate_unit_sha256':hashlib.sha256(updated).hexdigest(),'samples':[],
        'identity_backend_changed':False,'identity_database_configuration_changed':False,
        'metrics_enabled':True,'shadow_enabled':False,'runqueue_time_collected':False,'requested_observation_s':120,
        'gil_seconds':.005,'payload_sha256':PAYLOAD_SHA,'policy':AFFINITY_POLICY,
        'native_sources_unchanged_from_observer':True}
    def save():atomic(folder/'deployment-result.json',(json.dumps(report,indent=2)+'\n').encode())
    cursor=kernel_cursor();time.sleep(5)
    assert audio_warnings(cursor)==0,'USB baseline already warning; refuse live candidate'
    check=camera();healthy(check);assert check['pid']==before['pid']
    ui_idle();assert UNIT.read_bytes()==original_unit
    for p,expected in protected.items():assert digest(p)==expected
    timer='aura-affinity-live-rollback-'+str(os.getpid());report['timer']=timer
    command(['systemd-run','--unit='+timer,'--on-active=360s','/usr/bin/python3','-B',str(folder/'rollback.py')])
    armed=True
    try:
        service('stop','aura-camera-ui.service');assert UNIT.read_bytes()==original_unit
        atomic(UNIT,updated);service('daemon-reload');service('start','--no-block','aura-camera-ui.service')
        deadline=time.monotonic()+35
        while time.monotonic()<deadline:
            try:
                state=camera();report['latest_camera_seen']=state;healthy(state)
                if runtime_for(state['pid'])==(candidate,original_config):break
            except Exception:pass
            time.sleep(.4)
        else:raise RuntimeError('Capture candidate did not become ready')
        
        single_owner(state['pid'])
        report['candidate_camera_pid']=state['pid'];save()
        report['affinity_start']=affinity_snapshot(folder,state['pid'])
        first=state;started=time.monotonic();first_cpu=cpu()

        report['phase']='OBSERVING';report['candidate_camera_pid']=state['pid'];save()
        for index in range(25):
            state=camera();report['latest_camera_seen']=state;save();healthy(state)
            assert state['pid']==first['pid'] and state.get('shadow') is None
            observer=state['pipeline_metrics']['optional_diagnostics']['thread_sched_observer']
            assert observer['enabled'] and observer['mode']=='CALLING_THREAD_CONTEXT_SWITCHES_ONLY'
            assert not observer['disabled_after_slow_read'],'Observer stopped after slow read'
            state['elapsed_s']=time.monotonic()-started;report['samples'].append(state)
            assert audio_warnings(cursor)==0,'USB warning during copy-only candidate'
            for name,pid in unit_pids.items():assert service('show',name,'-p','MainPID','--value').strip()==pid
            report['elapsed_s']=state['elapsed_s'];save()
            if index<24:time.sleep(max(0,started+(index+1)*5-time.monotonic()))
        elapsed=time.monotonic()-started
        report['camera_after']=state;report['observed_seconds']=elapsed
        report['observed_yolo_hz']=(state['detected_frames']-first['detected_frames'])/elapsed
        report['observed_capture_hz']=(state['capture_frames']-first['capture_frames'])/elapsed
        report['cpu_window']=cpu_delta(first_cpu,cpu())
        assert elapsed>=120 and report['observed_yolo_hz']>=9
        for p,expected in protected.items():assert digest(p)==expected
        assert digest(path)==report['candidate_ui_sha256']
        report['usb_warning_count']=audio_warnings(cursor);assert report['usb_warning_count']==0
        
        report['affinity_end']=affinity_snapshot(folder,state['pid'])
        diagnostics=state['pipeline_metrics']['optional_diagnostics']
        assert not diagnostics['fault_events'] and not diagnostics['diagnostic_errors']
        assert diagnostics['counters']['yunet']['native_completed']>=100
        report['observed_yunet_hz']=(state['dpu_schedule']['optional']['yunet']['calls']-first['dpu_schedule']['optional']['yunet']['calls'])/elapsed
        assert report['observed_yunet_hz']>=2.
        ages=[row['face_targets']['source_age_ms'] for row in report['samples']
            if row.get('face_targets',{}).get('source_age_ms') is not None]
        report['freshness']={'scope':'sparse health snapshots, not a per-frame distribution',
            'samples':len(ages),'at_or_over_1000ms':sum(age>=1000 for age in ages),
            'maximum_ms':max(ages),'all_sampled_face_results_fresh':all(0<=age<1000 for age in ages)}
        report['throughput_and_optional_protection_passed']=True
        report['passed']=all(0<=age<1000 for age in ages)
        report['observation_status']='AFFINITY_120S_WITH_SEPARATE_FRESHNESS_GATE_NOT_SPEEDUP_OR_ROOT_CAUSE_PROOF'

    except Exception as exc:
        report['error']=type(exc).__name__+': '+str(exc)[:500]
        report['observation_status']='FAILED'
        try:report['fault_camera_snapshot']=camera()
        except Exception as fault_error:report['fault_snapshot_error']=type(fault_error).__name__
        save()
    finally:
        report['phase']='RESTORING';save()
        try:
            report['rollback_output']=command(['/usr/bin/python3','-B',str(folder/'rollback.py')],timeout=70)[-500:]
            deadline=time.monotonic()+35
            while time.monotonic()<deadline:
                try:
                    restored=camera();report['latest_restored_seen']=restored;healthy(restored)
                    if runtime_for(restored['pid'])==(BASE/'aura',original_config):break
                except Exception:pass
                time.sleep(.4)
            else:raise RuntimeError('Original retained camera did not recover')
            assert UNIT.read_bytes()==original_unit and restored.get('shadow') is None
            single_owner(restored['pid'])
            for name,expected in BASELINE.items():assert digest(BASE/'aura'/name)==expected
            for p,expected in protected.items():assert digest(p)==expected
            for name,pid in unit_pids.items():assert service('show',name,'-p','MainPID','--value').strip()==pid
            
            report['restored']=restored;report['rollback_verified']=True
            try:
                report['affinity_shutdown']=affinity_shutdown(folder,report.get('candidate_camera_pid',-1))
                if not report['affinity_shutdown']['clean_selected_thread_restoration_and_close']:
                    report['passed']=False;report['affinity_shutdown_error']='Clean selected-thread restoration/close not confirmed'
            except Exception as exc:
                report['passed']=False;report['affinity_shutdown_error']=type(exc).__name__+': '+str(exc)[:300]

            service('stop',timer+'.timer');armed=False
        except Exception as exc:
            report['rollback_verified']=False;report['passed']=False
            report['rollback_error']=type(exc).__name__+': '+str(exc)[:500]
        report['rollback_timer_left_armed']=armed;report['protected_unit_pids']=unit_pids
        report['complete']=True;report['phase']='FINISHED';save()
    print(json.dumps({'root':str(folder),'passed':report['passed'],'complete':True,
        'rollback_verified':report['rollback_verified']}),flush=True)

if __name__=='__main__':
    import sys
    source=Path(sys._getframe().f_code.co_filename).resolve();key=digest(source)[:16]
    launch=Path('/home/root/aura-dpu-vision-20261021/affinity-launches')/key
    launch.mkdir(parents=True,exist_ok=True)
    if os.environ.get('AURA_RUN_AFFINITY_LIVE')=='1':
        try:
            main();result={'finished':True,'scope':'Read affinity-live deployment-result for outcome and restoration'}
        except Exception as exc:result={'finished':True,'error':type(exc).__name__+': '+str(exc)[:500]}
        (launch/'launch-result.json').write_text(json.dumps(result,indent=2)+'\n')
    else:
        assert not (launch/'launch-result.json').exists()
        unit='aura-affinity-live-'+key
        command(['systemd-run','--unit='+unit,'--property=RuntimeMaxSec=300',
            '--setenv=AURA_RUN_AFFINITY_LIVE=1','/usr/bin/python3','-B',str(source)])
        print(json.dumps({'started':True,'unit':unit,'launch_result':str(launch/'launch-result.json')}),flush=True)
